   "case": "Bull",
   "probability": "20%",
   "driver": "Clean FDA response and clearance in H1 2027, second 510(k) accepted and a five-test CLIA waiver granted in 2028, 300 sites by end-2028 with utilisation at 3-4 panels a day and cartridge cost near $10 at 1M units.",
   "evidence": "The pivotal design (four sites, 1,150 patients, clinic staff as operators) matches FDA's waiver standard [S1]; no waived cardiac panel exists in the US today [S109, S25]; the cartridge patent family is granted and the panel is genuinely differentiated on sample type [S111].",
   "outcome": "Revenue $45-60M by 2030 and a trade sale at $450-550M (6-7x) in 2032-33; Meridian returns 2.7x at $140M pre-money and 4.6x at $70M.",
   "implication": "Invest, but only with a preference and a ratchet that capture the upside the bull case creates."
  },
  {
   "case": "Base",
   "probability": "50%",
   "driver": "Clearance in Q3 2027 after one further information cycle, second 510(k) in 2028 and waiver in 2029, 150-200 paying sites by end-2028, revenue $15-25M and 1-2 panels a day.",
   "evidence": "2025 average time to clearance was 146 days across 3,195 submissions and two-thirds of 510(k)s drew an information request [S118]; realised price $33.40 against $22.18 of Medicare payment caps clinic willingness to pay at launch [S119, S134]; site adds run at 1.1 a month [S109].",
   "outcome": "Trade sale at $200-250M (5-6x revenue) in 2031-33; Meridian returns 1.26x at $140M pre-money and 2.1x at $70M.",
   "implication": "The price has to carry the base case, not the bull case: lead at or below $100M, or tranche at $140M."
  },
  {
   "case": "Bear",
   "probability": "30%",
   "driver": "Clearance slips beyond 2027 or the troponin waiver is refused as first of kind; the stocking order never ships, the March 2027 runway forces a bridge or a sale, and the Corvia minority and the preference stack absorb the proceeds.",
   "evidence": "Cash of $6.9M against $1.15M a month runs out in March 2027 [S1]; the $35-40M requirement exceeds the $30M round [S1]; no troponin assay has been waived by application since 2019 [S109]; LumiraDx sold its platform out of distress for $295M upfront [S93].",
   "outcome": "Distressed asset sale at $30-80M in 2027-28; the senior 1x preference returns $12.4M of Meridian's $15M, 0.83x.",
   "implication": "Size and structure for the bear case: the preference is the only thing returning capital, and it does not cover the fee and the time."
  }
 ],
 "assumptions": [
