{"content":[{"type":"text","text":"scenario_analysis (by Lead Analyst):
{
 "scenarios": [
  {
   "case": "Bull",
   "probability": "20%",
   "driver": "Clean FDA response and clearance in H1 2027, second 510(k) accepted and a five-test CLIA waiver granted in 2028, 300 sites by end-2028 with utilisation at 3-4 panels a day and cartridge cost near $10 at 1M units.",
   "evidence": "The pivotal design (four sites, 1,150 patients, clinic staff as operators) matches FDA's waiver standard [S1]; no waived cardiac panel exists in the US today [S109, S25]; the cartridge patent family is granted and the panel is genuinely differentiated on sample type [S111].",
   "outcome": "Revenue $45-60M by 2030 and a trade sale at $450-550M (6-7x) in 2032-33; Meridian returns 2.7x at $140M pre-money and 4.6x at $70M.",
   "implication": "Invest, but only with a preference and a ratchet that capture the upside the bull case creates."
  },
  {
   "case": "Base",
   "probability": "50%",
   "driver": "Clearance in Q3 2027 after one further information cycle, second 510(k) in 2028 and waiver in 2029, 150-200 paying sites by end-2028, revenue $15-25M and 1-2 panels a day.",
   "evidence": "2025 average time to clearance was 146 days across 3,195 submissions and two-thirds of 510(k)s drew an information request [S118]; realised price $33.40 against $22.18 of Medicare payment caps clinic willingness to pay at launch [S119, S134]; site adds run at 1.1 a month [S109].",
   "outcome": "Trade sale at $200-250M (5-6x revenue) in 2031-33; Meridian returns 1.26x at $140M pre-money and 2.1x at $70M.",
   "implication": "The price has to carry the base case, not the bull case: lead at or below $100M, or tranche at $140M."
  },
  {
   "case": "Bear",
   "probability": "30%",
   "driver": "Clearance slips beyond 2027 or the troponin waiver is refused as first of kind; the stocking order never ships, the March 2027 runway forces a bridge or a sale, and the Corvia minority and the preference stack absorb the proceeds.",
   "evidence": "Cash of $6.9M against $1.15M a month runs out in March 2027 [S1]; the $35-40M requirement exceeds the $30M round [S1]; no troponin assay has been waived by application since 2019 [S109]; LumiraDx sold its platform out of distress for $295M upfront [S93].",
   "outcome": "Distressed asset sale at $30-80M in 2027-28; the senior 1x preference returns $12.4M of Meridian's $15M, 0.83x.",
   "implication": "Size and structure for the bear case: the preference is the only thing returning capital, and it does not cover the fee and the time."
  }
 ],
 "assumptions": [
  {
   "assumption": "FDA clears the two-assay 510(k) by Q3 2027 after the 2026-08-21 information request",
   "confidence": "low",
   "disproof": "No FDA acknowledgment letter for a 2026-05-18 filing, or a second information request after the December 2026 response",
   "impact": "-25% to -40% of equity value; every 2027 revenue line and the round's target close move",
   "early_warning": "The acknowledgment and information letters, and whether the response needs new clinical data"
  },
  {
   "assumption": "A five-test CLIA waiver for a cardiac panel is grantable by 2028-29",
   "confidence": "low",
   "disproof": "FDA refuses the waiver, requires a separate dual submission, or no troponin assay is waived by application",
   "impact": "-50% of addressable market; 300 sites and the FY2028 plan unreachable",
   "early_warning": "FDA pre-submission feedback and whether the waiver package is accepted for review"
  },
  {
   "assumption": "Commercial payers reimburse above Medicare and the second 510(k) adds NT-proBNP by 2028",
   "confidence": "low",
   "disproof": "Disclosed site collections near the $22.18 Medicare figure, or the second submission slipping past 2028",
   "impact": "-20% to -30% of revenue; the clinic stays cash-negative per cartridge",
   "early_warning": "Evaluation-site billing data by payer and CPT mix"
  },
  {
   "assumption": "Utilisation reaches at least two panels an analyzer a day at paying sites",
   "confidence": "low",
   "disproof": "Post-clearance reorder rates near the present 30.5 cartridges an analyzer a month",
   "impact": "-30% of revenue and the payback on each placed analyzer",
   "early_warning": "Monthly shipment and distributor inventory data"
  },
  {
   "assumption": "Cartridge cost falls to $10 at 1M units and $7.50 at 2M units on the pilot line's successor",
   "confidence": "medium",
   "disproof": "Yields at 500,000 units and the absence of a qualified second manufacturing source",
   "impact": "-10% to -15% of gross margin against the 76% target",
   "early_warning": "Cost per cartridge at 500,000 units and ISO 13485 certification timing"
  }
 ],
 "consensus": {
  "consensus": "The company and its advisers present a $2.41B US serviceable market, a unique five-test finger-stick panel, a 2027 cleared launch and 300 sites on the strength of a distributor letter; a generalist growth investor would underwrite the category and the site count.",
  "our_view": "The site count is real but the market is about $304M at observed use, the value inflection is the CLIA waiver in 2028-29 rather than the 510(k), the clinic is cash-negative on the launch menu, and $140M pre-money returns 1.4x even if the plan is delivered. We are below consensus on price and timing, not on the need.",
